# Generated by Phase: IMPLEMENT | Feature: EVOL-065
"""Where does this write land — one answer for every tool (EVOL-065).

Edit / Write / MultiEdit give `tool_input.file_path`. Bash gives the targets of the recognised writers in
`tool_input.command`: redirections (> >> >| &> &>> N>), tee, sed -i, cp (destination), mv (sources and
destination), python -c (ast: open(<literal>, <write mode>), Path(<literal>).write_text|write_bytes).
Anything else is not a writer (bash -c, a script on stdin, xargs / find -exec, build scripts, git apply — pre-commit
stays their backstop). A wrapper or a reserved word before the command (sudo, env, do, then, {, !) never hides it.

Verdict, in order: guarded (harness / user configuration, the git dir) → 1 · unresolved → 1 (route: Edit or Write)
· every target outside the project → 4 (nothing to judge; 3 is gate.py's import guard) · in-project targets → 0, one per line.
"""
from __future__ import annotations

import ast
import os
import re
import shlex
import subprocess
from pathlib import Path

# leading words that run the next word as the command: wrappers, and the reserved words a loop or a conditional opens with
PREFIX_WORDS = {"env", "command", "exec", "nohup", "time", "sudo", "if", "then", "elif", "else", "do", "while", "until", "{", "!"}
SEPARATORS = {";", "&&", "||", "|", "|&", "&", "(", ")", "\n", ";;"}
SPECIAL = "#;&|()<>\n"   # quoted or escaped, these are word characters: masked before shlex, restored in the word
MASK = {c: chr(0xE000 + i) for i, c in enumerate(SPECIAL)}
UNMASK = str.maketrans({v: k for k, v in MASK.items()})
BRACE = re.compile(r"\{[^{}]*(,|\.\.)[^{}]*\}")
FILE_REDIR = {">", ">>", ">|", "&>", "&>>", "<>"}
OPS = re.compile(r"&>>|&>|>>|>\||>&|<<<|<<|<&|<>|&&|\|\||\|&|;;|[;&|()<>\n]")
HEREDOC = re.compile(r"(?<!<)<<(-?)(?!<)[ \t]*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\2")
VAR = re.compile(r"\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))")
ASSIGN = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)=(.*)$", re.S)
ENV_FALLBACK = ("HOME", "CLAUDE_PROJECT_DIR", "TMPDIR")
EDIT_TOOLS = {"Edit", "Write", "MultiEdit"}


class Unresolved(Exception):
    """A recognised writer whose target cannot be named before it runs."""


def _drop_heredocs(text: str) -> str:
    out, pending = [], []
    for line in text.split("\n"):
        if pending:
            strip_tabs, word = pending[0]
            if (line.lstrip("\t") if strip_tabs else line) == word:
                pending.pop(0)
            continue
        for m in HEREDOC.finditer(line):
            pending.append((m.group(1) == "-", m.group(3)))
        out.append(HEREDOC.sub(" ", line))
    return "\n".join(out)


def _mask(text: str) -> str:
    """The quoting shlex drops, kept: a quoted or escaped special character is masked (a word character); an unquoted
    `#` at a word start drops the rest of the line (a comment); a backslash-newline joins the lines."""
    out, q, i, n = [], None, 0, len(text)
    while i < n:
        c = text[i]
        if c == "\\" and q != "'" and i + 1 < n:
            nxt = text[i + 1]
            if nxt == "\n":
                i += 2; continue
            if nxt in MASK:   # outside quotes the escape makes it a word character; inside "…" the backslash stays literal
                out.append(MASK[nxt] if q is None else c + MASK[nxt])
            else:
                out.append(c + nxt)
            i += 2; continue
        if q is None:
            if c in "'\"":
                q = c
            elif c == "#" and (not out or out[-1] in " \t\r;&|()<>\n"):   # an escaped pair (`\ #`) is a word, never its start
                j = text.find("\n", i)
                i = n if j < 0 else j
                continue
        elif c == q:
            q = None
        elif c in MASK:
            c = MASK[c]
        out.append(c)
        i += 1
    return "".join(out)


def _lex(text: str) -> list[str]:
    lx = shlex.shlex(_mask(text), posix=True, punctuation_chars=";&|()<>\n")
    lx.whitespace = " \t\r"
    lx.whitespace_split = True
    lx.commenters = ""
    words = []
    for tok in lx:
        if tok and all(c in ";&|()<>\n" for c in tok):
            words.extend(("op", o) for o in OPS.findall(tok))
        else:
            words.append(("w", tok.translate(UNMASK)))
    return words


def _commands(words) -> list:
    """Simple commands, with "(" and ")" kept as markers: a subshell's cd stays in the subshell."""
    cmds, cur = [], []
    for kind, tok in words:
        if kind == "op" and tok in SEPARATORS:
            if cur:
                cmds.append(cur)
            cur = []
            if tok in "()":
                cmds.append(tok)
            continue
        cur.append((kind, tok))
    if cur:
        cmds.append(cur)
    return cmds


class _Reader:
    def __init__(self, repo: Path, cwd: str | None, env: dict):
        self.repo, self.env = repo, env
        self.cwd: str | None = os.path.realpath(cwd) if cwd else str(repo)
        self.vars: dict[str, str | None] = {}
        self.targets: list[str] = []
        self.unresolved: str | None = None
        self.writer = False

    # ── words → paths ──
    def expand(self, word: str) -> str:
        if "`" in word or "$(" in word:
            raise Unresolved(f"a command substitution in «{word}»")
        if word == "~" or word.startswith("~/"):
            home = self.env.get("HOME")
            if not home:
                raise Unresolved(f"«{word}» names a home directory that is not set")
            word = home + word[1:]

        def sub(m):
            name = m.group(1) or m.group(2)
            val = self.vars.get(name) if name in self.vars else (self.env.get(name) if name in ENV_FALLBACK else None)
            if val is None:
                raise Unresolved(f"the variable ${name} is not set in the command")
            return val
        word = VAR.sub(sub, word)
        if "$" in word:
            raise Unresolved(f"a shell expansion in «{word}»")
        if any(c in word for c in "*?["):
            raise Unresolved(f"a glob in «{word}»")
        if BRACE.search(word):
            raise Unresolved(f"a brace expansion in «{word}»")
        return word

    def path(self, word: str) -> str:
        p = self.expand(word)
        if not os.path.isabs(p):
            if self.cwd is None:
                raise Unresolved(f"«{word}» is relative to a directory the command changed to through an expansion")
            p = os.path.join(self.cwd, p)
        return os.path.realpath(p)

    def hit(self, word: str):
        self.writer = True
        self.targets.append(self.path(word))

    # ── one simple command ──
    def run(self, cmd):
        args, redirs, i = [], [], 0
        while i < len(cmd):
            kind, tok = cmd[i]
            if kind == "op":
                nxt = cmd[i + 1][1] if i + 1 < len(cmd) and cmd[i + 1][0] == "w" else None
                if args and re.fullmatch(r"\d+", args[-1]) and tok in FILE_REDIR | {">&", "<", "<&"}:
                    args.pop()   # an all-digit word right before a redirection is its fd
                if tok in FILE_REDIR and nxt is not None:
                    redirs.append(nxt)
                elif tok == ">&" and nxt is not None and not re.fullmatch(r"\d+|-", nxt):
                    redirs.append(nxt)
                i += 2 if nxt is not None else 1
                continue
            args.append(tok)
            i += 1
        for r in redirs:
            self.hit(r)
        while args and ASSIGN.match(args[0]):
            name, val = ASSIGN.match(args.pop(0)).groups()
            try:
                self.vars[name] = self.expand(val) if val else ""
            except Unresolved:
                self.vars[name] = None
        while args and args[0] in PREFIX_WORDS | {"export"}:
            args.pop(0)
            while args and (args[0].startswith("-") or ASSIGN.match(args[0])):
                m = ASSIGN.match(args.pop(0))
                if m:
                    try:
                        self.vars[m.group(1)] = self.expand(m.group(2))
                    except Unresolved:
                        self.vars[m.group(1)] = None
        if not args:
            return
        name, rest = os.path.basename(args[0]), args[1:]
        if name == "cd":
            self._cd(rest)
        elif name == "tee":
            for a in _operands(rest):
                self.hit(a)
        elif name == "sed":
            self._sed(rest)
        elif name in ("cp", "mv"):
            self._copy(name, rest)
        elif re.fullmatch(r"python(\d+(\.\d+)?)?", name):
            self._python(rest)

    def _cd(self, rest):
        dest = rest[0] if rest else "~"
        try:
            self.cwd = self.path(dest) if dest != "-" else None
        except Unresolved:
            self.cwd = None

    def _sed(self, rest):
        inplace, script_given, operands, i = False, False, [], 0
        while i < len(rest):
            a = rest[i]
            if a == "--":
                operands.extend(rest[i + 1:]); break
            if a.startswith("--"):
                if a == "--in-place" or a.startswith("--in-place="):
                    inplace = True
                elif a in ("--expression", "--file", "--line-length"):
                    script_given = script_given or a != "--line-length"; i += 1
                elif a.startswith(("--expression=", "--file=")):
                    script_given = True
            elif a.startswith("-") and len(a) > 1:
                for j, c in enumerate(a[1:], 1):
                    if c == "i":
                        inplace = True; break
                    if c in "efl":
                        script_given = script_given or c != "l"
                        if j == len(a) - 1:
                            i += 1
                        break
            else:
                operands.append(a)
            i += 1
        if not inplace:
            return
        for a in operands[0 if script_given else 1:]:
            self.hit(a)

    def _copy(self, name, rest):
        target_dir, operands, i = None, [], 0
        while i < len(rest):
            a = rest[i]
            if a == "--":
                operands.extend(rest[i + 1:]); break
            if a in ("-t", "--target-directory"):
                target_dir = rest[i + 1] if i + 1 < len(rest) else None; i += 2; continue
            if a.startswith("--target-directory="):
                target_dir = a.split("=", 1)[1]
            elif a.startswith("-t") and len(a) > 2:
                target_dir = a[2:]
            elif a.startswith("-") and len(a) > 1:
                pass
            else:
                operands.append(a)
            i += 1
        brace = next((o for o in operands if BRACE.search(o)), None)
        if brace is not None:
            raise Unresolved(f"a brace expansion in «{brace}»")   # `cp f{,.bak}` is two operands the reader does not expand
        if target_dir is not None:
            dest, sources, into = target_dir, operands, True
        else:
            if len(operands) < 2:
                return
            dest, sources = operands[-1], operands[:-1]
            into = len(sources) > 1 or os.path.isdir(self.path(dest))
        d = self.path(dest)
        self.writer = True
        for s in sources:
            if name == "mv":
                self.hit(s)
            if not into:
                self.targets.append(d)
                continue
            try:
                self.targets.append(os.path.join(d, os.path.basename(self.expand(s).rstrip("/"))))
            except Unresolved:   # mv's sources are hit above: only cp reaches here
                self.targets.append(os.path.join(d, "*"))   # a source the reader cannot name, into a named directory: its content is judged

    def _python(self, rest):
        code, i = None, 0
        while i < len(rest):
            a = rest[i]
            if a == "-c":
                code = rest[i + 1] if i + 1 < len(rest) else None; break
            if a.startswith("-c"):
                code = a[2:]; break
            if not a.startswith("-") or a == "-":
                return   # a script or stdin: not a recognised writer
            i += 1
        if code is None:
            return
        try:
            tree = ast.parse(code)
        except (SyntaxError, ValueError):
            return
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                self._py_call(node)

    def _py_call(self, node):
        f = node.func
        lit = lambda n: n.value if isinstance(n, ast.Constant) and isinstance(n.value, str) else None   # noqa: E731
        if (isinstance(f, ast.Name) and f.id == "open") or (isinstance(f, ast.Attribute) and f.attr == "open" and isinstance(f.value, ast.Name) and f.value.id == "io"):
            mode = node.args[1] if len(node.args) > 1 else next((k.value for k in node.keywords if k.arg == "mode"), None)
            if mode is None:
                return
            m = lit(mode)
            if m is not None and not set(m) & set("wax+"):
                return
            target = node.args[0] if node.args else next((k.value for k in node.keywords if k.arg == "file"), None)
            if m is None or target is None or lit(target) is None:
                raise Unresolved("a python write whose target or mode is not a literal")
            self.hit(lit(target))
        elif isinstance(f, ast.Attribute) and f.attr in ("write_text", "write_bytes"):
            v = f.value
            if (isinstance(v, ast.Call) and ((isinstance(v.func, ast.Name) and v.func.id == "Path") or (isinstance(v.func, ast.Attribute) and v.func.attr == "Path"))
                    and v.args and lit(v.args[0]) is not None):
                self.hit(lit(v.args[0]))
            else:
                raise Unresolved("a python write whose target is not a literal Path")


def _operands(rest):
    out, opts = [], True
    for a in rest:
        if opts and a == "--":
            opts = False
        elif opts and a.startswith("-") and len(a) > 1:
            continue
        else:
            out.append(a)
    return out


def _bash(repo: Path, command: str, cwd: str | None, env: dict) -> _Reader:
    r = _Reader(repo, cwd, env)
    try:
        cmds = _commands(_lex(_drop_heredocs(command)))
    except ValueError:
        if re.search(r">|\b(tee|sed|cp|mv|python[0-9.]*)\b", command):
            r.writer, r.unresolved = True, "the command could not be read (unbalanced quotes)"
        return r
    stack = []
    for c in cmds:
        if c == "(":
            stack.append(r.cwd); continue
        if c == ")":
            if stack:
                r.cwd = stack.pop()
            continue
        try:
            r.run(c)
        except Unresolved as e:
            r.writer, r.unresolved = True, str(e)
            break
    return r


def _git(repo: Path, *args) -> str:
    try:
        return subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, timeout=10).stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def guarded_roots(repo: Path, env: dict) -> tuple[set[str], list[str]]:
    """(exact files, directory prefixes) guarded on every branch: the harness and user configuration, the git dir."""
    exact, prefixes = {os.path.realpath(repo / ".claude/settings.local.json")}, []
    home = env.get("HOME")
    if home:
        h = Path(home)
        exact |= {os.path.realpath(h / ".claude/settings.json"), os.path.realpath(h / ".claude/settings.local.json"), os.path.realpath(h / ".gitconfig")}
        prefixes += [os.path.realpath(h / ".claude/hooks"), os.path.realpath(h / ".config/git")]
    for flag in ("--git-common-dir", "--git-dir"):
        g = _git(repo, "rev-parse", flag)
        if g:
            prefixes.append(os.path.realpath(g if os.path.isabs(g) else repo / g))
    hp = _git(repo, "config", "--get", "core.hooksPath")
    if hp:
        if hp.startswith("~/") and home:
            hp = home + hp[1:]
        hp = os.path.realpath(hp if os.path.isabs(hp) else repo / hp)
        if not _within(hp, str(repo)):
            prefixes.append(hp)
    return exact, prefixes


def _within(path: str, root: str) -> bool:
    try:
        return os.path.commonpath([root, path]) == root
    except ValueError:
        return False


def targets(repo: Path, payload: dict, env: dict | None = None) -> dict:
    """Resolve a PreToolUse payload: {tool, writer, inside (repo-relative), guarded, unresolved, pathless}."""
    env = dict(os.environ if env is None else env)
    root = os.path.realpath(repo)
    ti = payload.get("tool_input") or {}
    tool = payload.get("tool_name") or ("Edit" if "file_path" in ti else "Bash" if "command" in ti else "")
    out = {"tool": tool, "writer": False, "inside": [], "guarded": [], "unresolved": None, "pathless": False}
    cwd = payload.get("cwd") or None
    if tool in EDIT_TOOLS:
        out["writer"] = True
        fp = ti.get("file_path") or ""
        if not fp:
            out["pathless"] = True
            return out
        paths = [os.path.realpath(fp if os.path.isabs(fp) else os.path.join(cwd or root, fp))]
    elif tool == "Bash":
        r = _bash(Path(root), str(ti.get("command") or ""), cwd, env)
        out["writer"], out["unresolved"], paths = r.writer, r.unresolved, r.targets
    else:
        return out
    exact, prefixes = guarded_roots(Path(root), env)
    for p in dict.fromkeys(paths):
        if p in exact or any(_within(p, g) for g in prefixes):
            out["guarded"].append(p)
        elif _within(p, root):
            out["inside"].append(os.path.relpath(p, root))
    return out


def verdict(repo: Path, payload: dict, env: dict | None = None) -> tuple[int, str]:
    """(rc, text): 0 + in-project targets one per line · 4 nothing to judge · 1 + the humanised reason.
    Never 3: that is gate.py's import guard (the package missing or broken), which a hook must read as a fault."""
    t = targets(repo, payload, env)
    if t["guarded"]:
        return 1, (f"BLOCKED: this write lands on the harness or user configuration ({', '.join(t['guarded'])}) — guarded on every branch.\n"
                   "Resolution: an agent never changes its own guard rails; ask the user to make that change by hand.")
    if t["unresolved"]:
        return 1, (f"BLOCKED: the shell command writes to a target the guard cannot name before it runs — {t['unresolved']}.\n"
                   "Resolution: make the write with Edit or Write, or give the shell command a literal path, so the branch rule and the planning stage can judge it.")
    if t["pathless"]:
        return 0, ""
    if not t["writer"] or not t["inside"]:
        return 4, ""
    return 0, "\n".join(t["inside"])
